#define max_lines 20#define max_cols 55char help_words[9][max_lines + 1][max_cols + 1] = {	{"Player Selection",	 " ",	 "This is where you select which players will be",	 "human and which will be simulated by the computer.",	 " ",	 " press 'k' - to move the cursor up",	 "       'j' - to move the cursor down",	 "     space - to toggle between human or computer",	 "       'b' - to display rule book",	 "       'q' - to quit the game",	 "       'v' - version display",         "    return - to begin play",	 "other features:",#if defined(SYS5) || defined(SYS5_3)	 " - shell window available by pressing '$' during play",#endif	 " - on-line help available by pressing '?' during play",	 " - redraw current window with '^L'",	 " - rule book available by pressing 'b' during play"},	{"End of Game",	 " ",	 "To continue the game press 'c', otherwise press",	 "'q' to quit.  Note that the high score file will",	 "only ever keep the highest score in the given round.",	 "The high score file can be displayed by pressing 's'",	 "at most times (including now).",	 " ",	 "The game can be reconfigured by pressing 'r'.",	 "This allows you to alter the number of players",	 "and which players are simulated."},	{"Select Dice to Hold",	 " ",	 "Select which dice you want to hold such that they",	 "will not be part of the next roll of the dice.",	 "Hold the dice that are likely to give the best",	 "score for your score-card.",	 " press 'l' - to move cursor right",	 "       'h' - to move cursor left",	 "     space - to hold/free die cursor is on",	 "    return - to roll dice",	 "       'r' - to get computer's advice on best hold",	 "       't' - shows value of dice in all categories",	 "       'a' - to hold all dice then roll",	 "       'b' - to display rule book",#if defined(SYS5) || defined(SYS5_3)	 "       '$' - to obtain shell window",#endif	 "       '!' - to obtain shell",	 "       'q' - to quit the game"},	{"Select Score Card Position",	 " ",	 "Select one of the available places to put the",	 "score for your final set of dice.  If your dice",	 "don't meet the requirements for the selected place",	 "you will receive 0 points (e.g. putting 1 2 3 6 6 in",	 "the 'three of a kind' position).",	 " ",	 " press 'k' - to move the cursor up",	 "       'j' - to move the cursor down",	 "    return - put score in indicated category",	 "       'r' - get computer's advice on best category",	 "       't' - shows value of dice in all categories",	 "       'b' - to display rule book",#if defined(SYS5) || defined(SYS5_3)	 "       '$' - to obtain shell window",#endif	 "       '!' - to obtain shell",	 "       'q' - to quit the game"},	{"Rules of Yahtzee",	 " ",	 "These are not the definitive rules for this game,",	 "many other versions exist, the game is sometimes",	 "referred to as 'dice poker'.  Possibly the rule",	 "with the greatest variation is the 'two hold' rule",	 "where the dice are held twice.  Some versions of",	 "Yahtzee only allow for one chance at holding dice.",	 "Allowing the player to hold twice, however, decreases",	 "the amount of 'luck' required to win, and increases",	 "the need for skillfull play."},	{"Help",	 " ",	 "Help is available at all stages of the game.",	 "Press 'q' or space to exit help.",	 " ",	 " press 'b' - to display rule book",	 "       's' - to display current scoreboard",	 "      '^L' - to redraw current window",	 "       '!' - to obtain shell escape",#if defined(SYS5) || defined(SYS5_3)	 "       '$' - enters shell window when pressed",#endif	 "       'v' - display yahtzee version"},	{"Player Count",	 " ",	 "Input the number of players, this version can have",	 "up to six players in a game. Also you can...",	 " ",	 "press 'q' - to quit the game",	 "     '^L' - redraws screen whenever pressed",	 "      'b' - displays the rule book whenever pressed",#if defined(SYS5) || defined(SYS5_3)	 "      '$' - enters shell window whenever pressed",#endif	 "      '!' - to obtain shell",	 "      'v' - displays yahtzee version",	 "      's' - displays the score board when pressed"},	{"High Score",	 " ",	 "This is the most recent high score file, it is",	 "updated at the end of each game.  Only the player",	 "with the highest score in a game is eligable to",	 "have their score recorded.",	 " ",	 "press 'q' - to resume the game",	 "     '^L' - to redraw the current window",#if defined(SYS5) || defined(SYS5_3)	 "      '$' - to obtain shell window",#endif	 "      '!' - to obtain shell",	 "      'v' - displays yahtzee version",	 "      'b' - to display the rule book"},	{"Shell Window",	 " ",	 "This is a limited shell window and should not be",	 "used for programs using full screen curses(3X)",	 "features (e.g. don't try to play yahtzee from",	 "inside this shell window).  Programs that expect",	 "input from stderr will also fail.",	 "To leave the shell and return to the game type",	 "exit at the shell prompt.  Also:",	 " ",	 "press '~.' - to kill shell",	 "      '~T' - to signal SIGTERM to shell",	 "      '~c' - toggle ticking clock on or off",	 "      '~~' - to send tilde to shell"}};